package com.genc.pccrms.model;

import jakarta.persistence.*;
import java.time.LocalDate;
import java.time.LocalTime;

@Entity
@Table(name = "Appointment")
public class Appointment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer appointmentId;

    @ManyToOne
    @JoinColumn(name = "patientId", nullable = false)
    private Patient patient;

    @Column(nullable = false, length = 100)
    private String doctorName;

    @Column(nullable = false)
    private LocalDate appointmentDate;

    @Column(nullable = false)
    private LocalTime appointmentTime;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AppointmentStatus appointmentStatus;

    public enum AppointmentStatus {
        BOOKED, COMPLETED, CANCELLED, NO_SHOW
    }

    // ===== Constructors =====
    public Appointment() {}

    public Appointment(Integer appointmentId, Patient patient, String doctorName,
                       LocalDate appointmentDate, LocalTime appointmentTime,
                       AppointmentStatus appointmentStatus) {
        this.appointmentId = appointmentId;
        this.patient = patient;
        this.doctorName = doctorName;
        this.appointmentDate = appointmentDate;
        this.appointmentTime = appointmentTime;
        this.appointmentStatus = appointmentStatus;
    }

    // ===== Getters =====
    public Integer getAppointmentId() { return appointmentId; }
    public Patient getPatient() { return patient; }
    public String getDoctorName() { return doctorName; }
    public LocalDate getAppointmentDate() { return appointmentDate; }
    public LocalTime getAppointmentTime() { return appointmentTime; }
    public AppointmentStatus getAppointmentStatus() { return appointmentStatus; }

    // ===== Setters =====
    public void setAppointmentId(Integer appointmentId) { this.appointmentId = appointmentId; }
    public void setPatient(Patient patient) { this.patient = patient; }
    public void setDoctorName(String doctorName) { this.doctorName = doctorName; }
    public void setAppointmentDate(LocalDate appointmentDate) { this.appointmentDate = appointmentDate; }
    public void setAppointmentTime(LocalTime appointmentTime) { this.appointmentTime = appointmentTime; }
    public void setAppointmentStatus(AppointmentStatus appointmentStatus) { this.appointmentStatus = appointmentStatus; }
}

package com.genc.pccrms.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import java.time.LocalDate;
import java.time.LocalTime;

@Entity
@Table(name = "Appointment")
public class Appointment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer appointmentId;

    @NotNull(message = "Patient is required")
    @ManyToOne
    @JoinColumn(name = "patientId", nullable = false)
    private Patient patient;

    @NotBlank(message = "Doctor name is required")
    @Size(min = 2, max = 100, message = "Doctor name must be between 2 and 100 characters")
    @Column(nullable = false, length = 100)
    private String doctorName;

    @NotNull(message = "Appointment date is required")
    @FutureOrPresent(message = "Appointment date must be today or in the future")
    @Column(nullable = false)
    private LocalDate appointmentDate;

    @NotNull(message = "Appointment time is required")
    @Column(nullable = false)
    private LocalTime appointmentTime;

    @NotNull(message = "Appointment status is required")
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AppointmentStatus appointmentStatus;

    public enum AppointmentStatus {
        BOOKED, COMPLETED, CANCELLED, NO_SHOW
    }

    // ===== Constructors =====
    public Appointment() {}

    public Appointment(Integer appointmentId, Patient patient, String doctorName,
                       LocalDate appointmentDate, LocalTime appointmentTime,
                       AppointmentStatus appointmentStatus) {
        this.appointmentId = appointmentId;
        this.patient = patient;
        this.doctorName = doctorName;
        this.appointmentDate = appointmentDate;
        this.appointmentTime = appointmentTime;
        this.appointmentStatus = appointmentStatus;
    }

    // ===== Getters =====
    public Integer getAppointmentId() { return appointmentId; }
    public Patient getPatient() { return patient; }
    public String getDoctorName() { return doctorName; }
    public LocalDate getAppointmentDate() { return appointmentDate; }
    public LocalTime getAppointmentTime() { return appointmentTime; }
    public AppointmentStatus getAppointmentStatus() { return appointmentStatus; }

    // ===== Setters =====
    public void setAppointmentId(Integer appointmentId) { this.appointmentId = appointmentId; }
    public void setPatient(Patient patient) { this.patient = patient; }
    public void setDoctorName(String doctorName) { this.doctorName = doctorName; }
    public void setAppointmentDate(LocalDate appointmentDate) { this.appointmentDate = appointmentDate; }
    public void setAppointmentTime(LocalTime appointmentTime) { this.appointmentTime = appointmentTime; }
    public void setAppointmentStatus(AppointmentStatus appointmentStatus) { this.appointmentStatus = appointmentStatus; }
}

package com.genc.pccrms.controller;

import com.genc.pccrms.model.Appointment;
import com.genc.pccrms.service.AppointmentService;
import com.genc.pccrms.service.PatientService;
import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@Controller
@RequestMapping("/appointments")
public class AppointmentController {

    @Autowired
    private AppointmentService appointmentService;

    @Autowired
    private PatientService patientService;

    // List all appointments
    @GetMapping
    public String listAppointments(Model model) {
        model.addAttribute("appointments", appointmentService.getAllAppointments());
        return "appointment/list";
    }

    // Show book form
    @GetMapping("/book")
    public String showBookForm(Model model) {
        model.addAttribute("appointment", new Appointment());
        model.addAttribute("patients", patientService.getAllPatients());
        return "appointment/book";
    }

    // Submit book form
    @PostMapping("/book")
    public String bookAppointment(@Valid @ModelAttribute("appointment") Appointment appointment,
                                  BindingResult result,
                                  @RequestParam("patientId") Integer patientId,
                                  Model model) {
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            return "appointment/book";
        }
        appointmentService.bookAppointment(patientId, appointment);
        return "redirect:/appointments";
    }

    // Show edit form
    @GetMapping("/edit/{id}")
    public String showEditForm(@PathVariable Integer id, Model model) {
        Appointment appointment = appointmentService.getAppointmentById(id)
                .orElseThrow(() -> new RuntimeException("Appointment not found"));
        model.addAttribute("appointment", appointment);
        model.addAttribute("patients", patientService.getAllPatients());
        model.addAttribute("statuses", Appointment.AppointmentStatus.values());
        return "appointment/edit";
    }

    // Submit edit form
    @PostMapping("/edit/{id}")
    public String updateAppointment(@PathVariable Integer id,
                                    @Valid @ModelAttribute("appointment") Appointment appointment,
                                    BindingResult result,
                                    @RequestParam("patientId") Integer patientId,
                                    Model model) {
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            model.addAttribute("statuses", Appointment.AppointmentStatus.values());
            return "appointment/edit";
        }
        appointmentService.updateAppointment(id, appointment, patientId);
        return "redirect:/appointments";
    }

    // Delete appointment
    @GetMapping("/delete/{id}")
    public String deleteAppointment(@PathVariable Integer id) {
        appointmentService.deleteAppointment(id);
        return "redirect:/appointments";
    }
}

package com.genc.pccrms.controller;

import com.genc.pccrms.model.Appointment;
import com.genc.pccrms.service.AppointmentService;
import com.genc.pccrms.service.PatientService;
import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.util.StringUtils;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@Controller
@RequestMapping("/appointments")
public class AppointmentController {

    @Autowired
    private AppointmentService appointmentService;

    @Autowired
    private PatientService patientService;

    // List all appointments
    @GetMapping
    public String listAppointments(Model model) {
        model.addAttribute("appointments", appointmentService.getAllAppointments());
        return "appointment/list";
    }

    // Show book form
    @GetMapping("/book")
    public String showBookForm(Model model) {
        model.addAttribute("appointment", new Appointment());
        model.addAttribute("patients", patientService.getAllPatients());
        return "appointment/book";
    }

    // Submit book form
    @PostMapping("/book")
    public String bookAppointment(@Valid @ModelAttribute("appointment") Appointment appointment,
                                  BindingResult result,
                                  @RequestParam(value = "patientId", required = false) String patientId,
                                  Model model) {
        Integer resolvedPatientId = resolvePatientId(patientId, result);
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            return "appointment/book";
        }
        appointmentService.bookAppointment(resolvedPatientId, appointment);
        return "redirect:/appointments";
    }

    // Show edit form
    @GetMapping("/edit/{id}")
    public String showEditForm(@PathVariable Integer id, Model model) {
        Appointment appointment = appointmentService.getAppointmentById(id)
                .orElseThrow(() -> new RuntimeException("Appointment not found"));
        model.addAttribute("appointment", appointment);
        model.addAttribute("patients", patientService.getAllPatients());
        model.addAttribute("statuses", Appointment.AppointmentStatus.values());
        return "appointment/edit";
    }

    // Submit edit form
    @PostMapping("/edit/{id}")
    public String updateAppointment(@PathVariable Integer id,
                                    @Valid @ModelAttribute("appointment") Appointment appointment,
                                    BindingResult result,
                                    @RequestParam(value = "patientId", required = false) String patientId,
                                    Model model) {
        Integer resolvedPatientId = resolvePatientId(patientId, result);
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            model.addAttribute("statuses", Appointment.AppointmentStatus.values());
            return "appointment/edit";
        }
        appointmentService.updateAppointment(id, appointment, resolvedPatientId);
        return "redirect:/appointments";
    }

    private Integer resolvePatientId(String patientId, BindingResult result) {
        if (!StringUtils.hasText(patientId)) {
            result.rejectValue("patient", "patient.required", "Patient is required");
            return null;
        }
        try {
            return Integer.valueOf(patientId);
        } catch (NumberFormatException ex) {
            result.rejectValue("patient", "patient.invalid", "Invalid patient selection");
            return null;
        }
    }

    // Delete appointment
    @GetMapping("/delete/{id}")
    public String deleteAppointment(@PathVariable Integer id) {
        appointmentService.deleteAppointment(id);
        return "redirect:/appointments";
    }
}

package com.genc.pccrms.controller;

import com.genc.pccrms.model.Invoice;
import com.genc.pccrms.service.BillingService;
import com.genc.pccrms.service.PatientService;
import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.util.StringUtils;
import org.springframework.web.bind.annotation.*;

@Controller
@RequestMapping("/billing")
public class BillingController {

    @Autowired
    private BillingService billingService;

    @Autowired
    private PatientService patientService;

    // List all invoices
    @GetMapping
    public String listInvoices(Model model) {
        model.addAttribute("invoices", billingService.getAllInvoices());
        return "billing/list";
    }

    // Show create form
    @GetMapping("/create")
    public String showCreateForm(Model model) {
        model.addAttribute("invoice", new Invoice());
        model.addAttribute("patients", patientService.getAllPatients());
        return "billing/create";
    }

    // Submit create form
    @PostMapping("/create")
    public String generateInvoice(@Valid @ModelAttribute("invoice") Invoice invoice,
                                  BindingResult result,
                                  @RequestParam(value = "patientId", required = false) String patientId,
                                  Model model) {
        Integer resolvedPatientId = resolvePatientId(patientId, result);
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            // Retain selected patient ID on form re-render
            if (patientId != null && !patientId.isEmpty()) {
                model.addAttribute("selectedPatientId", patientId);
            }
            return "billing/create";
        }
        billingService.generateInvoice(resolvedPatientId, invoice);
        return "redirect:/billing";
    }

    // Show edit form
    @GetMapping("/edit/{id}")
    public String showEditForm(@PathVariable Integer id, Model model) {
        Invoice invoice = billingService.getInvoiceById(id)
                .orElseThrow(() -> new RuntimeException("Invoice not found"));
        model.addAttribute("invoice", invoice);
        model.addAttribute("patients", patientService.getAllPatients());
        model.addAttribute("statuses", Invoice.ClaimStatus.values());
        return "billing/edit";
    }

    // Submit edit form
    @PostMapping("/edit/{id}")
    public String updateInvoice(@PathVariable Integer id,
                                @Valid @ModelAttribute("invoice") Invoice invoice,
                                BindingResult result,
                                @RequestParam(value = "patientId", required = false) String patientId,
                                Model model) {
        Integer resolvedPatientId = resolvePatientId(patientId, result);
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            model.addAttribute("statuses", Invoice.ClaimStatus.values());
            return "billing/edit";
        }
        billingService.updateInvoice(id, invoice, resolvedPatientId);
        return "redirect:/billing";
    }

    private Integer resolvePatientId(String patientId, BindingResult result) {
        if (!StringUtils.hasText(patientId)) {
            result.rejectValue("patient", "patient.required", "Patient is required");
            return null;
        }
        try {
            return Integer.valueOf(patientId);
        } catch (NumberFormatException ex) {
            result.rejectValue("patient", "patient.invalid", "Invalid patient selection");
            return null;
        }
    }

    // Approve claim
    @GetMapping("/approve/{id}")
    public String approveClaim(@PathVariable Integer id) {
        billingService.approveClaim(id);
        return "redirect:/billing";
    }

    // Reject claim
    @GetMapping("/reject/{id}")
    public String rejectClaim(@PathVariable Integer id) {
        billingService.rejectClaim(id);
        return "redirect:/billing";
    }

    // View invoice
    @GetMapping("/view/{id}")
    public String viewInvoice(@PathVariable Integer id, Model model) {
        Invoice invoice = billingService.getInvoiceById(id)
                .orElseThrow(() -> new RuntimeException("Invoice not found"));
        model.addAttribute("invoice", invoice);
        return "billing/view";
    }

    // Delete invoice
    @GetMapping("/delete/{id}")
    public String deleteInvoice(@PathVariable Integer id) {
        billingService.deleteInvoice(id);
        return "redirect:/billing";
    }
}

