package com.genc.pccrms.model;

import jakarta.persistence.*;
import java.time.LocalDate;

@Entity
@Table(name = "ClinicalRecord")
public class ClinicalRecord {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer recordId;

    @ManyToOne
    @JoinColumn(name = "patientId", nullable = false)
    private Patient patient;

    @Column(nullable = false)
    private LocalDate encounterDate;

    @Column(nullable = false, length = 20)
    private String diagnosisCode;

    @Column(columnDefinition = "TEXT")
    private String clinicalNotes;

    @Column(length = 255)
    private String vitalsSummary;

    public ClinicalRecord() {}

    public ClinicalRecord(Integer recordId, Patient patient, LocalDate encounterDate,
                          String diagnosisCode, String clinicalNotes, String vitalsSummary) {
        this.recordId = recordId;
        this.patient = patient;
        this.encounterDate = encounterDate;
        this.diagnosisCode = diagnosisCode;
        this.clinicalNotes = clinicalNotes;
        this.vitalsSummary = vitalsSummary;
    }

    public Integer getRecordId() { return recordId; }
    public Patient getPatient() { return patient; }
    public LocalDate getEncounterDate() { return encounterDate; }
    public String getDiagnosisCode() { return diagnosisCode; }
    public String getClinicalNotes() { return clinicalNotes; }
    public String getVitalsSummary() { return vitalsSummary; }

    public void setRecordId(Integer recordId) { this.recordId = recordId; }
    public void setPatient(Patient patient) { this.patient = patient; }
    public void setEncounterDate(LocalDate encounterDate) { this.encounterDate = encounterDate; }
    public void setDiagnosisCode(String diagnosisCode) { this.diagnosisCode = diagnosisCode; }
    public void setClinicalNotes(String clinicalNotes) { this.clinicalNotes = clinicalNotes; }
    public void setVitalsSummary(String vitalsSummary) { this.vitalsSummary = vitalsSummary; }
}

package com.genc.pccrms.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import java.time.LocalDate;

@Entity
@Table(name = "ClinicalRecord")
public class ClinicalRecord {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer recordId;

    @NotNull(message = "Patient is required")
    @ManyToOne
    @JoinColumn(name = "patientId", nullable = false)
    private Patient patient;

    @NotNull(message = "Encounter date is required")
    @PastOrPresent(message = "Encounter date cannot be in the future")
    @Column(nullable = false)
    private LocalDate encounterDate;

    @NotBlank(message = "Diagnosis code is required")
    @Pattern(regexp = "^[A-Z0-9]{2,20}$", message = "Diagnosis code must be alphanumeric (2-20 characters)")
    @Column(nullable = false, length = 20)
    private String diagnosisCode;

    @NotBlank(message = "Clinical notes are required")
    @Size(min = 5, max = 2000, message = "Clinical notes must be between 5 and 2000 characters")
    @Column(columnDefinition = "TEXT")
    private String clinicalNotes;

    @Size(max = 255, message = "Vitals summary must not exceed 255 characters")
    @Column(length = 255)
    private String vitalsSummary;

    public ClinicalRecord() {}

    public ClinicalRecord(Integer recordId, Patient patient, LocalDate encounterDate,
                          String diagnosisCode, String clinicalNotes, String vitalsSummary) {
        this.recordId = recordId;
        this.patient = patient;
        this.encounterDate = encounterDate;
        this.diagnosisCode = diagnosisCode;
        this.clinicalNotes = clinicalNotes;
        this.vitalsSummary = vitalsSummary;
    }

    public Integer getRecordId() { return recordId; }
    public Patient getPatient() { return patient; }
    public LocalDate getEncounterDate() { return encounterDate; }
    public String getDiagnosisCode() { return diagnosisCode; }
    public String getClinicalNotes() { return clinicalNotes; }
    public String getVitalsSummary() { return vitalsSummary; }

    public void setRecordId(Integer recordId) { this.recordId = recordId; }
    public void setPatient(Patient patient) { this.patient = patient; }
    public void setEncounterDate(LocalDate encounterDate) { this.encounterDate = encounterDate; }
    public void setDiagnosisCode(String diagnosisCode) { this.diagnosisCode = diagnosisCode; }
    public void setClinicalNotes(String clinicalNotes) { this.clinicalNotes = clinicalNotes; }
    public void setVitalsSummary(String vitalsSummary) { this.vitalsSummary = vitalsSummary; }
}

package com.genc.pccrms.controller;

import com.genc.pccrms.model.ClinicalRecord;
import com.genc.pccrms.service.ClinicalRecordService;
import com.genc.pccrms.service.PatientService;
import jakarta.validation.Valid;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.util.StringUtils;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@Controller
@RequestMapping("/ehr")
public class EhrController {

    @Autowired
    private ClinicalRecordService clinicalRecordService;

    @Autowired
    private PatientService patientService;

    @GetMapping
    public String listRecords(Model model) {
        model.addAttribute("records", clinicalRecordService.getAllRecords());
        return "ehr/list";
    }

    @GetMapping("/create")
    public String showCreateForm(Model model) {
        model.addAttribute("record", new ClinicalRecord());
        model.addAttribute("patients", patientService.getAllPatients());
        return "ehr/create";
    }

    @PostMapping("/create")
    public String createRecord(@Valid @ModelAttribute("record") ClinicalRecord record,
                               BindingResult result,
                               @RequestParam(value = "patientId", required = false) String patientId,
                               Model model) {
        Integer resolvedPatientId = resolvePatientId(patientId, result);
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            return "ehr/create";
        }
        clinicalRecordService.createRecord(resolvedPatientId, record);
        return "redirect:/ehr";
    }

    @GetMapping("/edit/{id}")
    public String showEditForm(@PathVariable Integer id, Model model) {
        ClinicalRecord record = clinicalRecordService.getRecordById(id)
                .orElseThrow(() -> new RuntimeException("Record not found"));
        model.addAttribute("record", record);
        model.addAttribute("patients", patientService.getAllPatients());
        return "ehr/edit";
    }

    @PostMapping("/edit/{id}")
    public String updateRecord(@PathVariable Integer id,
                               @Valid @ModelAttribute("record") ClinicalRecord record,
                               BindingResult result,
                               @RequestParam(value = "patientId", required = false) String patientId,
                               Model model) {
        Integer resolvedPatientId = resolvePatientId(patientId, result);
        if (result.hasErrors()) {
            model.addAttribute("patients", patientService.getAllPatients());
            return "ehr/edit";
        }
        clinicalRecordService.updateRecord(id, record, resolvedPatientId);
        return "redirect:/ehr";
    }

    private Integer resolvePatientId(String patientId, BindingResult result) {
        if (!StringUtils.hasText(patientId)) {
            result.rejectValue("patient", "patient.required", "Patient is required");
            return null;
        }
        try {
            return Integer.valueOf(patientId);
        } catch (NumberFormatException ex) {
            result.rejectValue("patient", "patient.invalid", "Invalid patient selection");
            return null;
        }
    }

    @GetMapping("/delete/{id}")
    public String deleteRecord(@PathVariable Integer id) {
        clinicalRecordService.deleteRecord(id);
        return "redirect:/ehr";
    }

    @GetMapping("/view/{id}")
    public String viewRecord(@PathVariable Integer id, Model model) {
        ClinicalRecord record = clinicalRecordService.getRecordById(id)
                .orElseThrow(() -> new RuntimeException("Record not found"));
        model.addAttribute("record", record);
        return "ehr/view";
    }
}

